import{_ as t,c as e,o as p,af as r,ai as s,aj as _,ak as i}from"./chunks/framework.zX5h-Rkw.js";const u=JSON.parse('{"title":"1.2 百年南武，弦歌不辍","description":"","frontmatter":{"title":"1.2 百年南武，弦歌不辍"},"headers":[],"relativePath":"archives_n_arts/arts/nambu_blue/1.2.md","filePath":"archives_n_arts/arts/nambu_blue/1.2.md"}'),n={name:"archives_n_arts/arts/nambu_blue/1.2.md"};function o(l,a,c,m,d,h){return p(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="一" tabindex="-1">一 <a class="header-anchor" href="#一" aria-label="Permalink to “一”">​</a></h1><h2 id="_2-百年南武-弦歌不辍" tabindex="-1">2. 百年南武，弦歌不辍 <a class="header-anchor" href="#_2-百年南武-弦歌不辍" aria-label="Permalink to “2. 百年南武，弦歌不辍”">​</a></h2><p>百年南武，沧海桑田，弦歌不辍；育人为本，厚德载物，拓展潜能，誉满南粤。诚所谓“周虽旧邦，其命维新”者也！</p><p>南武是一所有故事的学校。故事沉淀文化，文化承载初心，初心彰显精神。</p><p>1901年春，黄晦闻、杨渐逵、黄汉莼、欧阳曰瑚、李蕴石、谢英伯、何锡明等人以“启迪民智，移风化俗”故，在广州的河南（老广州人对珠江以南的海珠区的称呼）龙溪首约成立群学书社，这就是南武学校的前身。因龙溪首约场地太小，群学书社后转迁至海幢寺里的圆照堂，对其房舍稍加修葺供社员使用，同时，“群学书社”改名为“南武公学会”，内设编辑、辩论、体育三部，并成立群众阅书报处，作为市民公共阅读场所。因为当时河南除了私塾外没有学堂，所以，南武公学会再增设智育部筹办学堂，在圆照堂附殿设一间男女同学的教室，招募南武公学会同人子女12人就读，这便是广州市第一间男女同学的学校，取名为“南武两等小学堂”，并向广东省学务处呈请备案，南武两等小学堂于1905年3月3日开学。“两等小学堂”是清末学堂的一种制度，小学堂分“初等”和“高等”，合并设立者称“两等”。“初等”六岁人学，修业五年，后改四年；“高等”修业四年。由于清廷规定男女不能同校学习，1908年男女学生被迫分开上学，女生所在的学校为洁芳女子小学堂。谢英伯为南武两等小学堂的首任校长，南武公学会同人分任各科教职，如有张劭闻、潘达微、高仑（即高剑父）等人任教。当时他们在南武所担任的全部为义务职，学校只供教员膳食，不计薪金。第一学期结束，学生增加到55人。后来，南武学校把南武两等小学堂开学之日期——3月3日定为建校纪念日，并于每年3月第一周的周日举办校庆活动。“逢五小庆，逢十大庆”已成南武典制。</p><p>南武学校是在“废科季，兴新学”的背景下成立的。清朝末期，教育制度有了一些改良：1902年布了《钦定学堂章程》；1903年又颁布系列章程；1905年废止实行了一千三百余年的“科举制度”，新学在广东开始“萌芽”。当时广东地区办的新学大概可分为三类：一类是公办背景的新学，如广雅书院，增设外语和数学，并将成绩好的学生派往外国留学。同时，开办幼儿和女子教育，设建蒙学堂，蒙养院；第二类是教会办的学校，如外国人在广东开办的第一间教会女子书院——真光书院。第三类就是“公知”办的私立性质的新学，如河南的私立南武学堂，首设体育课，井首开男女同校之先河。</p><p>谢英伯任南武两等小学堂校长不到一年，1906年南武公学会理事会延聘何剑吴任校长。何剑吴任校长后，大加扩充校舍，锐意进取办学，不到一年，学生激增至130余人，除初等小学外，开办高等小学一个班。1907年7月，初等小学第一届毕业生有12人；1909年7月，高等小学第一届毕业生有14人。1912年添办中学，学校取名为“南武中学”，小学为“南武中学附属小学”。1914年夏，南武中学旧制第一届毕业，有毕业生8人。1914年夏至1927年夏，共有12届旧制中学毕业生，毕业人数为113人。自何剑吴接任校长后，即以烈士陈天华之语——“坚忍奉公，力学爱国”为校训，强调“德、智、体、美、群”五育并举，提倡爱国主义教育，倡导不遗余力革命，为洗雪“东亚病夫”的耻辱，唤起青少年学生之觉醒。他提倡“南武精神就是体育精神”十分重视体育，把体育列为主要课程，以加强学生体质锻炼，常常在课余组织各类体育活动。学校培养了不少优秀运动员，也曾在多届省运动会上获得团体冠军，特别是在早期远东运动会上，如1913年在菲律宾举行的第一届远东运动会上，南武学生陈彦获得我国在国际体育比赛中的第一枚金牌——跳远比赛金牌，丘纪祥获220码走第三名，许民辉、陈谨、何琳等6名南武学生入选中国男子排球队；在第二、三届远东运动会上，中国男子排球队连续两届获得男子排球冠军，为推动和发展体育运动，提高运动技术水平，作出了很大的贡献，为祖国增光添彩。当时的南武就有“体育固驰名于南国，文化亦推重于中原”的美誉，不仅学校体育誉满华南，名扬东南亚，学生陈彦、许民辉、丘纪祥也被称为“南武三杰”。</p><p>1922年1月，学校改行“新学制”（即“壬戌学制”），实行“三三制”（即初中三年，高中三年），称为“两级中学”，先办初级中学共三个班。1923年，新学制初中第一届毕业生有16人。至1948年夏，共有25届新学制初中毕业生，总计1410人。1926年8月，南武中学增设高级中学普通科、商科、师范三科。1927年暑假后改高中普通科为文理两科。1928年7月，第一届高中文理科毕业，有文科毕业生14人，理科毕业生5人。至1931年，文理科共有4届毕业生，总计46人。1931年11月22日，坚忍堂奠基。1932年春，建筑奉公楼用作学生宿舍。1933年春，因开辟同福路，南武中学被一分为二，路南为中学，路北为小学。1936年，拆西边旧饭堂课室，改建为红墙绿瓦的平房5间。</p><p>1937年，因战乱学校撤离广州。1938年秋，广州沦陷，学校停办，校址被日本侵略者占为“宪兵司令部”，又改作“陆军伤兵疗养院”。1939年春，迁校至香港，租得九龙深水埗南昌街南中中学旧址，开设香港南武中学，只 办初中和小学，由郭熙棠出任校长，有学生300余人。也有师生迁广西办南武中学。1941年冬，香港沦陷，香港南武中学停办。1942年9月，迁址曲江复办南武中学，先是借励群学校教室两间，开办高中、初中一年级各一班。学生约有80人。1943年，在曲江河边厂车站北小岗建新校址，学生达256人。1944年春，曲江沦陷，校舍被日本侵略者占用，曲江南武中学被迫停办。1945年秋，广州光复，南武中小学招生复课，至1949年夏，已发展为河南享有盛名，颇具规模，拥有1000多名学生，兼收寄宿生的全日制完全中学。</p><p>南武，在八字校训和南武精神的教育影响下，在“德、智、体、美、群”五字方针的指引下，培养出来的学生，大多热爱祖国，学习勤奋，生活勤苦朴素，爱好体育运动，他们毕业后献身于祖国，服务于人民，造福于社会，大多有所建树。身居海外者，亦事业有成，知名之士甚多。早年教育部部长黄炎培先生曾对南武中学作出“北有南开，南有南武”的高度评价，诚非偶然。这里特别要提的是，中华人民共和国成立前南武四十多年的发展历程和成就与何剑吴先生有着密切的关系。何剑吴先生先后六任南武校长，献身教育，献身南武，贡献卓著，深为当时广大员工和学生爱戴，至今仍受广大老校友的怀念和崇敬。</p><p>中华人民共和国成立后，所有的私立学校都逐步改为公立学校，自1952年起,广州市政府直接管理南武学校，并决定在南武校址先后改办广州市第一职业学校、广州市财经技术学校和广州市财政学校。1954年秋，广州市政府决定在南武校址同时开办全日制完全中学,名为“广州市第十九中学”，设初中、高中一年级各4个班，招学生约350人。是年，建筑立新楼。1957年夏，广州市第十九中学初中、高中第一届学生毕业。1959年、南武学校改名为“广州市第三十三中学”，附设龙溪南小学。1960年，学校锐意改革创新，经广州市政府批准，广州市第十九中学、广州市第三十三中学、广州市海珠区龙溪南小学合并，在南武校址开办广州市实验学校，校长先为罗文运，后为王真。广州市实验学校在学制方面从小学到高中毕业实行“十年一贯制”， 在教材和教法等方面进行了一系列改革，并取得良好成绩，被评为广州市、广东省和全国先进单位，成为当时广州市的重点中学。时任市长朱光曾到校视察。1965年，广州市实验学校第一届高中毕业生中考上高等院校的占总数的68%。1966年夏，因<strong>无产阶级文化大革命</strong>【为编者所改动】，所有学校停课。1968年秋学校复课。更名为“广州市第五十八中学”，设初中各年级共48个班，学生激增至约2640人。1970年，拆旧礼堂，建筑力学楼。1971年秋至1980年夏，学生人数进一步激增，每学年学生总数达4000人以上，其中最高峰为1973年夏，学生在校人数为4300多人。广州市第五十八中学时期，学校重视从德、智、体诸方面培养人才，多次被评为广州市先进单位。1979届高中毕业生黄晓明、张远超参加全国高考，分别取得省、市理科类应届毕业生成绩总分第一名、第二名，同被中国科技大学优先录取。1977届高中毕业生苏健翔代表国家，参加了1983年在保加利亚举行的第三届世界航海模型锦标赛，打破世界纪录，荣获世界冠军。1983届初中毕业生梁艳华被保送到广州市中心业余体校学习，成长为中国武术队队员。1984年11月，学校复名为广州市南武中学至今。</p><p>2000年9月，开办南武实验学校。2004年8月，广州市第一零二中学并入南武中学，建新校区在杏园大街81号，是为“广州市南武中学初中部”。2008年，学校通过“广东省国家级示范性普通高中”初期评估，2013年3月通过终期评估，广东省教育厅授其“广东省国家级示范性普通高中”匾。2015年3月，成立广州市南武教育集团，成员学校有广州市南武中学、广州市江南外国语学校、广州市第三十三中学、广州市南武实验学校（国有民办）、广州市海珠区南武小学、广州市海珠区南武实验小学。2019年9月，广州市海珠区教育局批准吸收广州市岭南画派纪念中学为南武教育集团成员学校。2021年5月，广州市海珠区南洲小学升级为“九年一贯制”学校，学校更名为“广州市海珠区南武文润学校”，成为南武教育集团成员校，纳入集团管理。2022年5月，广州市岭南画派纪念中学与广州市南武中学合并重组，南武中学为“一校三区”（三区是指同福路高中部、杏园大街初中部、江南西玫瑰二街岭南画派纪念校区）。2022年7月，广州市南武实验学校由民办转为公办。同时，集团筹办广州市南武中学附属学校，并于2023年9月正式招生开学，招小学一年级3个班，学生120人；初中一年级6个班，学生300人。2024年5月，广州市第三十三中学正式更名为“广州市南武第二实验学校”。自此，广州市南武教育集团形成“8校13校区”格局，“大南武”由此得名:</p><p><img src="'+s+'" alt="2-1"></p><p>图2-1：南武中学高中部</p><p><img src="'+_+'" alt="2-2"></p><p>图2-2：南武中学初中部</p><p><img src="'+i+'" alt="2-3"></p><p>图2-3：南武中学岭南画派纪念校区</p>',18)])])}const b=t(n,[["render",o]]);export{u as __pageData,b as default};
